create table if not exists public.product_snapshots(id bigint generated always as identity primary key,product_id uuid not null references public.products on delete cascade,captured_at timestamptz not null default now(),ranking int not null,period text not null check(period in('1D','7D','30D')),sold_count bigint,gmv_min numeric(14,2),gmv_max numeric(14,2),gmv_estimated numeric(14,2),price numeric(12,2),creator_count int,video_count int,review_count int,rating numeric(3,2),raw_payload jsonb not null);
create index product_snapshots_product_idx on public.product_snapshots(product_id);create index product_snapshots_captured_idx on public.product_snapshots(captured_at desc);create index product_snapshots_period_idx on public.product_snapshots(period);create index product_snapshots_ranking_idx on public.product_snapshots(ranking);
create table if not exists public.creator_snapshots(id bigint generated always as identity primary key,creator_id uuid not null references public.creators on delete cascade,captured_at timestamptz not null default now(),ranking int not null,period text not null check(period in('1D','7D','30D')),gmv_min numeric(14,2),gmv_max numeric(14,2),gmv_estimated numeric(14,2),sales bigint,video_count int,raw_payload jsonb not null);create index creator_snapshots_history_idx on public.creator_snapshots(creator_id,captured_at desc);create index creator_snapshots_ranking_idx on public.creator_snapshots(period,ranking);
create table if not exists public.video_snapshots(id bigint generated always as identity primary key,video_id uuid not null references public.videos on delete cascade,creator_id uuid references public.creators,product_id uuid references public.products,captured_at timestamptz not null default now(),ranking int not null,period text not null check(period in('1D','7D','30D')),views bigint,sales bigint,gmv_min numeric(14,2),gmv_max numeric(14,2),gmv_estimated numeric(14,2),raw_payload jsonb not null);create index video_snapshots_history_idx on public.video_snapshots(video_id,captured_at desc);create index video_snapshots_ranking_idx on public.video_snapshots(period,ranking);
create table if not exists public.lives(id uuid primary key default gen_random_uuid(),external_id text unique not null,name text not null,created_at timestamptz default now());create table if not exists public.live_snapshots(id bigint generated always as identity primary key,live_id uuid not null references public.lives on delete cascade,captured_at timestamptz not null default now(),ranking int not null,period text not null check(period in('1D','7D','30D')),gmv_min numeric(14,2),gmv_max numeric(14,2),gmv_estimated numeric(14,2),raw_payload jsonb not null);create index live_snapshots_history_idx on public.live_snapshots(live_id,captured_at desc);
create table if not exists public.data_sync_runs(id uuid primary key default gen_random_uuid(),provider text not null,started_at timestamptz not null default now(),finished_at timestamptz,status text not null check(status in('running','success','failed')),products_received int not null default 0,creators_received int not null default 0,videos_received int not null default 0,lives_received int not null default 0,error_message text);
create index data_sync_runs_started_idx on public.data_sync_runs(started_at desc);
create table if not exists public.tiktok_connections(id uuid primary key default gen_random_uuid(),user_id uuid references auth.users on delete cascade,open_id text not null,seller_name text,seller_base_region text,shop_cipher text,access_token_ciphertext text not null,refresh_token_ciphertext text not null,access_token_expires_at timestamptz not null,refresh_token_expires_at timestamptz not null,granted_scopes text[] not null default '{}',created_at timestamptz default now(),updated_at timestamptz default now(),unique(user_id,open_id));alter table public.tiktok_connections enable row level security;revoke all on public.tiktok_connections from anon,authenticated;
